import { useState } from 'react';
import { JxButton, JxInputField, JxSelect, JxSwitch } from '@jinx-ui/react';

export type ProfileLanguage = 'ru' | 'en';

export interface ProfileSettings {
  name: string;
  language: ProfileLanguage;
  emailNotifications: boolean;
}

export interface ProfileSettingsFormProps {
  initialSettings?: Partial<ProfileSettings>;
  onSave: (settings: ProfileSettings) => void;
}

const LANGUAGE_OPTIONS = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'Английский' },
];

export default function ProfileSettingsForm({
  initialSettings,
  onSave,
}: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings?.name ?? '');
  const [language, setLanguage] = useState<ProfileLanguage>(
    initialSettings?.language ?? 'ru',
  );
  const [emailNotifications, setEmailNotifications] = useState(
    initialSettings?.emailNotifications ?? false,
  );
  const [nameError, setNameError] = useState('');

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const trimmedName = name.trim();

    if (!trimmedName) {
      setNameError('Укажите имя');
      return;
    }

    setNameError('');
    onSave({ name: trimmedName, language, emailNotifications });
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-gap, 16px)',
      }}
    >
      <JxInputField
        label="Имя"
        required
        value={name}
        onChange={(event) => {
          setName(event.target.value);
          if (nameError) setNameError('');
        }}
        errorText={nameError}
        placeholder="Как вас зовут"
      />

      <JxSelect
        label="Язык интерфейса"
        options={LANGUAGE_OPTIONS}
        value={language}
        onValueChange={(value) => setLanguage(value as ProfileLanguage)}
        placeholder="Выберите язык"
      />

      <JxSwitch
        label="Уведомления на почту"
        name="emailNotifications"
        checked={emailNotifications}
        onChange={(event) => setEmailNotifications(event.target.checked)}
      />

      <div style={{ display: 'flex', gap: 'var(--jx-gap, 8px)' }}>
        <JxButton variant="primary" type="submit">
          Сохранить
        </JxButton>
      </div>
    </form>
  );
}

